import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _grad_max(h, eps=1e-12):
    """Gradient of max(conv(h,h)) w.r.t. h, averaged over near-max knots."""
    N = len(h)
    conv = np.convolve(h, h)
    m = conv.max()
    ks = np.flatnonzero(conv >= m - eps * max(1.0, abs(m)))
    g = np.zeros(N)
    for k in ks:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        g[lo:hi + 1] += 2.0 * h[k - np.arange(lo, hi + 1)]
    g /= len(ks)
    return g


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_C = np.inf

    if start is not None:
        s0 = np.asarray(start, dtype=float)
        if s0.ndim == 1 and s0.size > 0 and np.all(np.isfinite(s0)) and s0.sum() > 0:
            c0 = _C(s0)
            if c0 < best_C:
                best_C = c0
                best_h = s0.copy()

    # Candidate lengths: keep start's length if present, also try a few.
    lengths = []
    if best_h is not None:
        lengths.append(best_h.size)
    for L in (50, 200, 500, 1500, 4000):
        if L not in lengths:
            lengths.append(L)

    rng = np.random.default_rng(987654321)

    for N in lengths:
        if time.process_time() >= deadline:
            break

        # seed: upscale/downscale current best, else flat
        if best_h is not None and best_h.size != N:
            x_old = np.linspace(0, 1, best_h.size)
            x_new = np.linspace(0, 1, N)
            h = np.interp(x_new, x_old, best_h)
        elif best_h is not None:
            h = best_h.copy()
        else:
            h = np.ones(N)
        h = np.clip(h, 0.0, None)
        if h.sum() <= 0:
            h = np.ones(N)
        h /= h.sum()

        # projected gradient ascent on 1/C = sum^2 / (2N * max conv)
        # Work with normalized h (sum=1) so we minimize max conv.
        # Local optimization from a few perturbed seeds.
        n_restarts = 3
        for r in range(n_restarts):
            if time.process_time() >= deadline:
                break
            if r == 0:
                hc = h.copy()
            else:
                hc = np.maximum(h * np.exp(rng.normal(0, 0.1, size=N)), 0)
                if hc.sum() <= 0:
                    continue
                hc /= hc.sum()

            eta = 0.05
            local_best = hc.copy()
            local_C = _C(hc)
            it = 0
            while time.process_time() < deadline:
                it += 1
                g = _grad_max(hc)
                # subtract mean to keep sum-preserving direction, then project
                g -= g.mean()
                hc = hc - eta * g
                hc = np.clip(hc, 0.0, None)
                s = hc.sum()
                if s <= 0:
                    hc = np.ones(N) / N
                else:
                    hc /= s

                c = _C(hc)
                if c < local_C:
                    local_C = c
                    local_best = hc.copy()
                    eta *= 1.02
                else:
                    eta *= 0.97
                if eta < 1e-6:
                    eta = 0.05
                if it % 10 == 0 and time.process_time() >= deadline:
                    break

            if local_C < best_C:
                best_C = local_C
                best_h = local_best.copy()

    if best_h is None:
        return np.ones(50)
    return best_h

