def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    # Build starting point
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.ndim != 1 or hs.size == 0 or not np.all(np.isfinite(hs)) or hs.sum() <= 0:
            hs = None
    else:
        hs = None

    if hs is None:
        N = 200
        x = np.linspace(-0.5, 0.5, N)
        h = np.cos(np.pi * x) ** 2 + 1e-3
    else:
        # Upsample by repeat factor 4 (N=50 -> N=200), or nearest integer factor
        N0 = hs.size
        factor = max(1, int(round(200 / N0))) if N0 < 200 else 1
        if N0 * factor > 30000:
            factor = max(1, 30000 // N0)
        h = np.repeat(hs, factor).astype(float)

    best = h.copy()
    bestC = _C(best)

    # Also track original start
    origC = np.inf
    if hs is not None:
        origC = _C(hs)

    N = best.size
    rng = np.random.default_rng(12345)

    # Cyclic coordinate line search with multiplicative factors
    factors = np.array([0.2, 0.1, 0.05, 0.02, 0.01, 0.005, 0.002, 0.001])

    while time.process_time() < deadline and factors.max() > 1e-6:
        improved_any = False
        order = rng.permutation(N)
        for i in order:
            if time.process_time() >= deadline:
                break
            cur = best[i]
            if cur <= 0:
                # try small positive bump
                cur = 1e-6
            for d in factors:
                if time.process_time() >= deadline:
                    break
                # try up then down
                for sign in (1.0, -1.0):
                    newval = cur * np.exp(sign * d)
                    if newval <= 0:
                        continue
                    old = best[i]
                    best[i] = newval
                    c = _C(best)
                    if c < bestC - 1e-12:
                        bestC = c
                        improved_any = True
                        cur = newval
                        break
                    else:
                        best[i] = old
                else:
                    continue
                break
        if not improved_any:
            factors = factors * 0.7

    # Return best of upsampled-refined and original start
    if hs is not None and origC <= bestC:
        return hs
    return best

