    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 400
    # midpoints on [-1/4, 1/4]
    x = (np.arange(N) + 0.5) / N - 0.5
    u = 2.0 * x

    def make_h(a):
        # a = (a1, a2, a3); a0 irrelevant (scaling)
        e = a[0] * u + a[1] * u * u + a[2] * u * u * u
        e = e - np.max(e)  # avoid overflow
        return np.exp(e)

    def obj(a):
        return _C(make_h(a))

    # Build initial guesses
    inits = []
    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size and hs.sum() > 0 and np.all(np.isfinite(hs)):
            # interpolate log(start) onto our grid
            xs = (np.arange(hs.size) + 0.5) / hs.size - 0.5
            us = 2.0 * xs
            logs = np.log(np.maximum(hs, 1e-12))
            # least squares fit of cubic (without constant) to logs
            A = np.vstack([us, us * us, us * us * us]).T
            coef, *_ = np.linalg.lstsq(A, logs, rcond=None)
            inits.append(coef)
    # default smooth bump init
    inits.append(np.array([0.0, -2.0, 0.0]))
    rng = np.random.default_rng(12345)
    for _ in range(2):
        inits.append(rng.normal(0.0, 1.0, size=3))

    best_a = None
    bestC = np.inf
    for a0 in inits:
        if time.process_time() >= deadline:
            break
        try:
            res = minimize(
                obj, a0, method='Nelder-Mead',
                options={'maxiter': 400, 'xatol': 1e-6, 'fatol': 1e-9},
            )
            cC = res.fun
            if np.isfinite(cC) and cC < bestC:
                bestC = cC
                best_a = res.x
        except Exception:
            continue

    if best_a is None:
        # fallback
        best_a = np.array([0.0, -2.0, 0.0])
        bestC = obj(best_a)

    best_h = make_h(best_a)
    best_h = np.maximum(best_h, 0.0)

    # Compare against start by exact C
    if start is not None:
        hs = np.asarray(start, dtype=float).ravel()
        if hs.size and hs.sum() > 0 and np.all(np.isfinite(hs)):
            if _C(hs) <= bestC:
                return hs

    return best_h

import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _conv_and_grad(h):
    """Return max(conv(h,h)) and averaged gradient of the max over near-max knots."""
    N = len(h)
    conv = np.convolve(h, h)
    m = conv.max()
    # treat all knots within a small relative window of the max
    tol = 1e-7 * max(1.0, abs(m))
    ks = np.flatnonzero(conv >= m - tol)
    g = np.zeros(N)
    for k in ks:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        idx = np.arange(lo, hi + 1)
        g[lo:hi + 1] += 2.0 * h[k - idx]
    g /= len(ks)
    return m, g


def _refine(h, deadline, rng, restarts=4):
    """Minimize max(conv)/sum^2 (i.e. C) with gradient descent on max-conv, sum fixed."""
    N = len(h)
    h = h.astype(float)
    if h.sum() <= 0:
        h = np.ones(N)
    h /= h.sum()

    best_h = h.copy()
    best_C = _C(h)

    for r in range(restarts):
        if time.process_time() >= deadline:
            break
        if r == 0:
            hc = h.copy()
        else:
            hc = np.maximum(h * np.exp(rng.normal(0, 0.05, size=N)), 1e-12)
            hc /= hc.sum()

        eta = 0.02
        local_best = hc.copy()
        local_C = _C(hc)
        stall = 0
        while time.process_time() < deadline:
            m, g = _conv_and_grad(hc)
            g -= g.mean()  # preserve sum direction
            hc = hc - eta * g
            hc = np.clip(hc, 0.0, None)
            s = hc.sum()
            if s <= 0:
                hc = np.ones(N) / N
            else:
                hc /= s

            c = _C(hc)
            if c < local_C - 1e-13:
                local_C = c
                local_best = hc.copy()
                eta *= 1.05
                stall = 0
            else:
                eta *= 0.92
                stall += 1
            if eta < 1e-8:
                break
            if stall > 200:
                break

        if local_C < best_C:
            best_C = local_C
            best_h = local_best.copy()

    return best_h, best_C


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(20240607)

    best_h = None
    best_C = np.inf

    if start is not None:
        s0 = np.asarray(start, dtype=float)
        if s0.ndim == 1 and s0.size > 0 and np.all(np.isfinite(s0)) and s0.sum() > 0:
            c0 = _C(s0)
            if c0 < best_C:
                best_C = c0
                best_h = s0.copy()

    # Primary strategy: refine at the start's own length (it was tuned for N=50).
    if best_h is not None:
        h, c = _refine(best_h, deadline, rng, restarts=5)
        if c < best_C:
            best_C = c
            best_h = h

    # Try a couple of alternative lengths, seeding by interpolation of current best.
    lengths = []
    if best_h is not None:
        lengths.append(best_h.size)
    for L in (50, 100, 150, 300):
        if L not in lengths:
            lengths.append(L)

    for N in lengths:
        if time.process_time() >= deadline:
            break
        if best_h is None:
            h = np.ones(N)
        elif best_h.size == N:
            h = best_h.copy()
        else:
            x_old = np.linspace(0, 1, best_h.size)
            x_new = np.linspace(0, 1, N)
            h = np.interp(x_new, x_old, best_h)
        h = np.clip(h, 0.0, None)
        if h.sum() <= 0:
            h = np.ones(N)
        h, c = _refine(h, deadline, rng, restarts=3)
        if c < best_C:
            best_C = c
            best_h = h

    if best_h is None:
        return np.ones(50)
    return best_h
